def count_grey_cells(R, C, K):
    def is_grey(row, col):
        # Check if there is no common 1 bit in the binary representation of row and col
        return all(((row >> i) & 1) != ((col >> i) & 1) for i in range(max(len(bin(row)), len(bin(col))) - 2))

    # Precompute the number of grey cells up to each row
    grey_count_up_to_row = [0] * R
